WITH base AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, CAST(amount AS INT) AS amount_int FROM orders WHERE order_date > DATE '2023-09-19' AND store_id IS NOT NULL) SELECT channel, SUM(CASE WHEN channel = 'partner' THEN amount_int ELSE 0 END) AS partner_amount_int, COUNT(DISTINCT channel) AS distinct_channels, SIZE(COLLECT_SET(status)) AS num_status FROM base GROUP BY 1;
